# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# setup_default_Depletion ----
## Setup ----
data <- FIMSFrame(data_limited_tuna)

## IO correctness ----
test_that("`setup_default_Depletion()` works with correct inputs", {
  result <- setup_default_Depletion(data = data)
  value_of <- function(label) result[["value"]][result[["label"]] == label]
  type_of <- function(label) {
    unique(result[["estimation_type"]][result[["label"]] == label])
  }

  #' @description Test that the depletion defaults are all Depletion rows.
  expect_true(all(result[["module_name"]] == "Depletion"))
  #' @description Test that the depletion defaults are all of module type PellaTomlinson.
  expect_true(all(result[["module_type"]] == "PellaTomlinson"))
  #' @description Test that the defaults start from a growth rate of 0.2, a carrying capacity of 10 times the largest catch (37500 mt) and a Schaefer shape of 2.
  expect_equal(
    object = exp(c(
      value_of("log_growth_rate"), value_of("log_carrying_capacity"),
      value_of("log_shape")
    )),
    expected = c(0.2, 375000, 2)
  )
  #' @description Test that the growth rate and carrying capacity are estimated and the shape and initial depletion are constant.
  expect_equal(
    object = vapply(
      c(
        "log_growth_rate", "log_carrying_capacity", "log_shape",
        "log_init_depletion"
      ),
      type_of, character(1),
      USE.NAMES = FALSE
    ),
    expected = c("fixed_effects", "fixed_effects", "constant", "constant")
  )
  #' @description Test that the initial depletion is 1, an unfished start.
  expect_equal(value_of("log_init_depletion"), 0)
  log_depletion <- dplyr::filter(result, .data[["label"]] == "log_depletion")
  #' @description Test that log_depletion has 1 value per year from the second year.
  expect_equal(log_depletion[["timing"]], 1968:1989)
  #' @description Test that log_depletion values are random effects.
  expect_true(all(log_depletion[["estimation_type"]] == "random_effects"))
  #' @description Test that log_depletion values have a process distribution.
  expect_true(all(log_depletion[["distribution_type"]] == "process"))
  log_sd <- dplyr::filter(result, .data[["label"]] == "log_sd")
  #' @description Test that the process log_sd is log(0.1).
  expect_equal(log_sd[["value"]], log(0.1))
  #' @description Test that the process log_sd is constant.
  expect_equal(log_sd[["estimation_type"]], "constant")
  #' @description Test that the process log_sd names log_depletion as its target.
  expect_equal(log_sd[["target_label"]], "log_depletion")
  #' @description Test that `setup_default_parameters()` returns the depletion defaults for a surplus production model.
  expect_equal(
    object = setup_default_parameters(data, model_type = "SurplusProduction"),
    expected = result
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
test_that("`setup_default_Depletion()` returns correct error messages", {
  #' @description Test that `setup_default_Depletion()` errors when `data` is not a FIMSFrame.
  expect_error(
    object = setup_default_Depletion(data = data_limited_tuna),
    regexp = "FIMSFrame"
  )
  #' @description Test that `setup_default_Depletion()` errors for a module type that does not exist.
  expect_error(
    object = setup_default_Depletion(data = data, module_type = "Fox"),
    regexp = "must be one of"
  )
  #' @description Test that `setup_default_parameters()` errors for a model type that does not exist.
  expect_error(
    object = setup_default_parameters(data, model_type = "DelayDifference"),
    regexp = "must be one of"
  )
})
